# Calculate Insertion Loss for each muffler
insertion_loss = {
    name: [b - m for b, m in zip(baseline_avg, powers)]
    for name, powers in mufflers.items()
}

# Plot using Plotly
fig = go.Figure()

for name, il in insertion_loss.items():
    fig.add_trace(go.Scatter(x=hz, y=il, mode="lines+markers", name=name))

fig.update_layout(
    title="Insertion Loss vs Frequency for Different Mufflers",
    xaxis=dict(title="Frequency (Hz)", type="log"),
    yaxis=dict(title="Insertion Loss (dB)"),
    template="plotly_white",
    legend_title="Muffler",
)

